/* ------------------------------------------------------------------ *
 * Rendering
 * ------------------------------------------------------------------ */

const maintState = { query: "", equip: "", open: null, tab: "figures" };

function maintNormalize(s) {
  return (s || "").toString().toLowerCase().replace(/[^a-z0-9]/g, "");
}

// A garbled tag (faded/embossed plate, or a hurried type-in) swaps stamped
// DIGITS for lookalike LETTERS: 0<->O/D/Q, 1<->I/L, 5<->S, 8<->B, 6<->G, 2<->Z.
// The Tag Scanner already forgives this via ocrModelCandidates() (app.js). The
// Maintenance Figures search reuses the SAME re-reads so a model that scans or
// types slightly wrong still lands on its entry — "share across" with the
// scanner. Candidates are computed ONCE per query and cached, not per entry.
let _maintOcrCache = { q: null, cands: null };
function maintQueryCandidates(q) {
  if (_maintOcrCache.q === q) return _maintOcrCache.cands;
  let cands = [];
  try {
    if (typeof ocrModelCandidates === "function") {
      const raw = (q || "").toUpperCase().replace(/\s+/g, "");
      cands = ocrModelCandidates(raw).map(maintNormalize).filter(Boolean);
    }
  } catch (e) { cands = []; }
  _maintOcrCache = { q, cands };
  return cands;
}

function maintMatches(entry, q) {
  if (!q) return true;
  const n = maintNormalize(q);
  if (!n) return true;
  const hay = [entry.brand, entry.model, entry.summary, entry.equip]
    .concat(entry.match || [])
    .map(maintNormalize);
  const hit = (needle) => !!needle && hay.some(h =>
    h.includes(needle) ||
    (needle.length >= 4 && h.startsWith(needle.slice(0, 4)) && h.includes(needle.slice(0, 4))));
  if (hit(n)) return true;
  // OCR-forgiving fallback: only kicks in when the plain match missed AND the
  // query has digit/letter lookalikes to re-read (otherwise the list is empty).
  for (const cand of maintQueryCandidates(q)) {
    if (hit(cand)) return true;
  }
  return false;
}

// The 4-char fuzzy rule in maintMatches() is deliberately loose so a partial
// tag still finds SOMETHING — but it also means "GCVC950915DXAC" lights up the
// GMVC96/GCVC96 entry (same "GCVC" prefix, different platform, different
// orifice/valve/supply figures). Ranking fixes that without tightening the
// match: score = longest common prefix between the query (or an OCR re-read
// of it) and any model token, so the entry that actually carries the model
// string wins. Tokens are match[] plus model split on "/" — the parenthetical
// note in model ("(GCVC950915DX figures)") is ignored — and each of those
// again with the brand in front, so "carrier 59" scores against "carrier59tp6"
// instead of losing to a fan coil whose match[] happens to start with the
// word "Carrier". maintMatches() itself is unchanged; app.js still calls it.
function maintMatchScore(entry, q) {
  if (!maintMatches(entry, q)) return 0;
  const needles = [maintNormalize(q)].concat(maintQueryCandidates(q)).filter(Boolean);
  if (!needles.length) return 0;
  const parts = (s) => (s || "").split(" (")[0].split("/");
  const models = (entry.match || []).concat(parts(entry.model)).map(maintNormalize).filter(Boolean);
  const brands = parts(entry.brand).map(maintNormalize).filter(Boolean);
  const tokens = models.concat(brands.flatMap(b => models.map(m => b + m)));
  let best = 0;
  for (const n of needles) {
    for (const t of tokens) {
      const max = Math.min(n.length, t.length);
      let i = 0;
      while (i < max && n[i] === t[i]) i++;
      if (i > best) best = i;
    }
  }
  return best;
}

// v185: the 4-char fuzzy rule crosses EQUIPMENT TYPES. "EL19KPV" (a Lennox heat
// pump) shares "el19" with the ML195 furnace entry, "EL180UH" (a furnace) with
// the XP25 heat pump, so a tech who scanned a heat pump could open gas-furnace
// figures. An entry is an EXACT match when the query (or an OCR re-read) starts
// with one of its whole model tokens; anything else is only a look-alike. For
// look-alikes we ask the Tag Scanner's MODEL_PATTERNS what kind of equipment the
// model is, and hide entries of a different kind.
const MAINT_EQUIP_COMPAT = {
  "Gas Furnace": ["Gas Furnace"],
  "Condenser/Heat Pump": ["Condenser", "Heat Pump", "Condenser/Heat Pump"],
  "Air Handler": ["Air Handler", "Electric Furnace"],
  "Electric Furnace": ["Electric Furnace", "Air Handler"],
  "Mini-Split": ["Mini-Split"]
};
function maintEsc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, m => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[m]));
}
function maintIsExact(entry, q) {
  const needles = [maintNormalize(q)].concat(maintQueryCandidates(q)).filter(Boolean);
  const parts = (s) => (s || "").split(" (")[0].split("/");
  const models = (entry.match || []).concat(parts(entry.model)).map(maintNormalize).filter(t => t.length >= 4);
  const brands = parts(entry.brand).map(maintNormalize).filter(Boolean);
  const tokens = models.concat(brands.flatMap(b => models.map(m => b + m)));
  return needles.some(n => tokens.some(t => n.startsWith(t)));
}
function maintQueryEquip(q) {
  if (typeof MODEL_PATTERNS === "undefined") return null;
  const raw = (q || "").toUpperCase().replace(/\s+/g, "");
  if (!raw) return null;
  let cands = [raw];
  try { if (typeof ocrModelCandidates === "function") cands = cands.concat(ocrModelCandidates(raw)); } catch (e) { /* keep raw */ }
  for (const c of cands) {
    const p = MODEL_PATTERNS.find(x => x.re.test(c));
    if (p) return p.equipment || null;
  }
  return null;
}
// One place that decides what a model-number query shows. exact: entries that
// carry the model. approx: same-kind look-alikes (only when nothing is exact).
// hidden: how many look-alikes were dropped for being a different kind.
function maintLookup(q, list) {
  const pool = list || MAINT_SPECS.filter(e => maintMatches(e, q));
  const exact = pool.filter(e => maintIsExact(e, q));
  if (exact.length) return { exact, approx: [], equip: null, hidden: 0 };
  const equip = maintQueryEquip(q);
  const ok = equip && MAINT_EQUIP_COMPAT[equip];
  const approx = ok ? pool.filter(e => ok.includes(e.equip)) : pool;
  return { exact: [], approx, equip, hidden: pool.length - approx.length };
}

function renderMaint() {
  const results = document.getElementById("maintResults");
  const empty = document.getElementById("maintEmptyState");
  const input = document.getElementById("maintSearchInput");
  const equipSel = document.getElementById("maintEquipChips");
  if (!results) return;

  // Populate the equipment filter once.
  if (equipSel && !equipSel.dataset.filled) {
    const kinds = [...new Set(MAINT_SPECS.map(e => e.equip))].sort();
    equipSel.innerHTML = '<option value="">All equipment</option>' +
      kinds.map(k => `<option value="${k}">${k}</option>`).join("");
    equipSel.dataset.filled = "1";
    equipSel.addEventListener("change", () => {
      maintState.equip = equipSel.value;
      renderMaint();
    });
  }

  if (input && !input.dataset.wired) {
    input.dataset.wired = "1";
    input.addEventListener("input", () => {
      maintState.query = input.value;
      maintState.open = null;
      renderMaint();
    });
  }

  let list = MAINT_SPECS.filter(e =>
    (!maintState.equip || e.equip === maintState.equip) &&
    maintMatches(e, maintState.query)
  );

  // Most-specific entry first — for model-NUMBER queries only (the query has a
  // digit). Once such a query has a solid (5+ char) model-token prefix hit, the
  // weaker fuzzy hits are noise — drop them. Word/brand queries ("furnace",
  // "heat pump", "Nordyne", "GMVC") skip ranking and list everything as before.
  const qn = maintNormalize(maintState.query);
  let notice = "";
  if (/[0-9]/.test(qn) && list.length) {
    // v185: exact model matches only; otherwise same-kind look-alikes, clearly
    // labelled, and never a different kind of equipment (see maintLookup).
    const lk = maintLookup(maintState.query, list);
    const q = maintEsc(maintState.query.trim());
    if (lk.exact.length) {
      list = lk.exact;
    } else {
      list = lk.approx;
      const kind = lk.equip ? maintEsc(lk.equip.toLowerCase()) + " " : "";
      notice = list.length
        ? `<div class="maint-flag"><div class="maint-flag-title">Not an exact match for ${q}</div>No figures for this model yet. These are the closest ${kind}entries by model prefix, and they may be a different series with different numbers. Check the series on the rating plate before you use any figure.</div>`
        : `<div class="maint-flag"><div class="maint-flag-title">No figures for ${q} yet</div>The only look-alike entries are a different kind of equipment, so they're hidden. Check Manuals, or use Request Info.</div>`;
    }
  }
  if (/[0-9]/.test(qn) && list.length) {
    const scored = list.map((e, i) => ({ e, i, s: maintMatchScore(e, maintState.query) }));
    const top = scored.reduce((m, x) => Math.max(m, x.s), 0);
    if (top >= 5) {
      list = scored.filter(x => x.s === top)
        .sort((a, b) => b.s - a.s || a.i - b.i)
        .map(x => x.e);
    }
  }

  if (!list.length) {
    results.innerHTML = notice;
    empty.classList.toggle("hidden", !!notice);
    return;
  }
  empty.classList.add("hidden");

  results.innerHTML = notice + list.map((entry, i) => {
    const id = entry.brand + "|" + entry.model;
    const isOpen = maintState.open === id;
    return `
      <article class="card maint-card">
        <button class="maint-head" data-maint-toggle="${id}">
          <div>
            <div class="maint-title">${entry.brand} ${entry.model}</div>
            <div class="maint-sub">${entry.summary}</div>
          </div>
          <span class="maint-caret">${isOpen ? "▾" : "▸"}</span>
        </button>
        ${isOpen ? maintBody(entry) : ""}
      </article>`;
  }).join("");

  results.querySelectorAll("[data-maint-toggle]").forEach(btn => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.maintToggle;
      maintState.open = maintState.open === id ? null : id;
      maintState.tab = "figures";
      renderMaint();
      if (typeof trackEvent === "function" && maintState.open) {
        trackEvent("maint figures " + id);
      }
    });
  });

  results.querySelectorAll("[data-maint-manuals]").forEach(btn => {
    btn.addEventListener("click", () => openManualsForModel(btn.dataset.maintManuals));
  });

  results.querySelectorAll("[data-maint-tab]").forEach(btn => {
    btn.addEventListener("click", () => {
      maintState.tab = btn.dataset.maintTab;
      renderMaint();
    });
  });
}

// What to search Manuals for from an entry: the tech's own query when it was a
// model number, else the entry's first model-number match token.
function maintManualQuery(entry) {
  const q = (maintState.query || "").trim();
  if (/[0-9]/.test(q) && q.replace(/[^A-Za-z0-9]/g, "").length >= 4) return q;
  const tok = (entry.match || []).find(t => /[0-9]/.test(t) && t.replace(/[^A-Za-z0-9]/g, "").length >= 4);
  return tok || entry.model;
}

function maintBody(entry) {
  const tabs = `
    <div class="maint-tabs">
      <button class="maint-tab ${maintState.tab === "figures" ? "on" : ""}" data-maint-tab="figures">Figures</button>
      <button class="maint-tab ${maintState.tab === "checklist" ? "on" : ""}" data-maint-tab="checklist">Recommended list</button>
    </div>`;

  if (maintState.tab === "checklist") {
    const cl = MAINT_CHECKLISTS[entry.checklist];
    if (!cl) return tabs + `<div class="maint-empty">No checklist mapped for this unit yet.</div>`;
    return tabs + `
      <div class="maint-body">
        <div class="maint-cl-title">${cl.title}</div>
        <div class="maint-note">${cl.note}</div>
        ${cl.sections.map(s => `
          <div class="maint-group">
            <div class="maint-group-title">${s.title}</div>
            <ul class="maint-cl">
              ${s.items.map(it => `<li>${it}</li>`).join("")}
            </ul>
          </div>`).join("")}
      </div>`;
  }

  return tabs + `
    <div class="maint-body">
      ${(entry.flags || []).map(f => `
        <div class="maint-flag">
          <div class="maint-flag-title">${f.title}</div>
          <div>${f.body}</div>
        </div>`).join("")}
      ${entry.groups.map(g => `
        <div class="maint-group">
          <div class="maint-group-title">${g.title}</div>
          <table class="maint-table">
            ${g.rows.map(r => `
              <tr class="${r.key ? "maint-key" : ""}">
                <td class="maint-label">${r.label}</td>
                <td class="maint-value">${r.value}</td>
              </tr>`).join("")}
          </table>
        </div>`).join("")}
      <div class="maint-source">${entry.source} · Always confirm against the rating plate on the unit in front of you.</div>
      ${typeof openManualsForModel === "function" ? `<button type="button" class="maint-manuals-btn" data-maint-manuals="${maintEsc(maintManualQuery(entry))}">📄 Manuals for this unit</button>` : ""}
    </div>`;
}
